  { type: 'li', text: 'jam' }] };

function diff(a, b, path, patches) {
  if (!a) { patches.push('ADD ' + path + ' <' + b.type + '>' + (b.text || '')); return; }
  if (!b) { patches.push('REMOVE ' + path); return; }
  if (a.type !== b.type) { patches.push('REPLACE ' + path); return; } // different type: rebuild
  if (a.text !== b.text) patches.push('SET_TEXT ' + path + ' "' + a.text + '" -> "' + b.text + '"');
  const n = Math.max((a.children || []).length, (b.children || []).length);
  for (let i = 0; i < n; i++) {   // compare children at the same position only
    diff((a.children || [])[i], (b.children || [])[i], path + '/' + i, patches);
  }
}
